package dk.stream.android;
import android.content.Context;
import java.io.*;
import java.util.*;
import org.json.*;

@androidx.media3.common.util.UnstableApi
final class DownloadPlanner {
 static JSONObject plan(Context context,JSONObject request)throws Exception{return plan(context,request,null);}
 static JSONObject plan(Context context,JSONObject request,DownloadControl control)throws Exception{
  Library library=new LibraryStore(context).load();JSONArray files=new JSONArray();Set<String> names=new HashSet<>();Set<String> visited=new HashSet<>();WebDavClient cloud=library.pcloud==null?null:new WebDavClient(library.pcloud);
  try{JSONArray items=request.getJSONArray("items");for(int i=0;i<items.length();i++){if(control!=null)control.await();JSONObject item=items.getJSONObject(i);if(item.has("file")){LocalMedia local=LocalMedia.from(item.getJSONObject("file"));ArrayDeque<LocalMedia> pending=new ArrayDeque<>();pending.add(local);while(!pending.isEmpty()){if(control!=null)control.await();if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();LocalMedia entry=pending.removeFirst();if(!visited.add(entry.uri))continue;if(entry.folder){List<LocalMedia> children=new ArrayList<>();if(PcloudDocument.is(entry.uri)){if(cloud==null)throw new IOException("pCloud account missing");for(WebDavClient.Entry child:cloud.listAll(PcloudDocument.url(library.pcloud,entry.uri)))children.add(child.media(library.pcloud));}else children=localChildren(context,entry);for(LocalMedia child:children){String relative=entry==local?child.name:entry.name+"/"+child.name;pending.add(new LocalMedia(child.uri,relative,child.mime,child.folder));}}else add(files,names,entry.name,entry.uri,entry.mime);}}
   else{Playlist.Kind kind=Playlist.Kind.valueOf(item.getString("kind"));if(kind==Playlist.Kind.TV)continue;String series=item.isNull("series")?null:item.optString("series",null);if(series!=null){Library.Source source=library.findSource(item.getString("source"));if(source==null||!source.xtream)throw new IOException("Series source missing");Playlist.Channel channel=new Playlist.Channel(item.getString("name"),item.optString("url"),item.optString("group"),kind,series);for(Playlist.Channel episode:new XtreamClient(source.server,source.username,source.password).episodes(channel))add(files,names,item.getString("name")+"/"+DownloadNames.file(episode.name,episode.url),episode.url,mime(episode.url));}else{String url=Playlist.httpUrl(item.getString("url")).toString();add(files,names,DownloadNames.file(item.getString("name"),url),url,mime(url));}}
  }}finally{if(cloud!=null)cloud.cancel();}
  if(control!=null)control.await();if(files.length()==0)throw new IOException("No files to download");boolean zip=files.length()>1;String filename=zip?DownloadNames.clean(request.optString("name","Download"))+".zip":files.getJSONObject(0).getString("name");if(!zip)filename=filename.substring(filename.lastIndexOf('/')+1);return new JSONObject().put("files",files).put("zip",zip).put("name",filename).put("mime",zip?"application/zip":files.getJSONObject(0).optString("mime","application/octet-stream"));
 }
 private static List<LocalMedia> localChildren(Context context,LocalMedia folder){android.net.Uri parent=android.net.Uri.parse(folder.uri);android.net.Uri children=android.provider.DocumentsContract.buildChildDocumentsUriUsingTree(parent,android.provider.DocumentsContract.getDocumentId(parent));List<LocalMedia> result=new ArrayList<>();String[] columns={android.provider.DocumentsContract.Document.COLUMN_DOCUMENT_ID,android.provider.DocumentsContract.Document.COLUMN_DISPLAY_NAME,android.provider.DocumentsContract.Document.COLUMN_MIME_TYPE};try(android.database.Cursor cursor=context.getContentResolver().query(children,columns,null,null,null)){if(cursor==null)throw new IllegalStateException("Folder unavailable");while(cursor.moveToNext()){String mime=cursor.getString(2);result.add(new LocalMedia(android.provider.DocumentsContract.buildDocumentUriUsingTree(parent,cursor.getString(0)).toString(),cursor.getString(1),mime,android.provider.DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)));}}return result;}
 private static void add(JSONArray files,Set<String> used,String name,String uri,String mime)throws Exception{if(files.length()>=50000)throw new IOException("Too many files");files.put(new JSONObject().put("name",DownloadNames.unique(name,used)).put("uri",uri).put("mime",mime==null||mime.isEmpty()?"application/octet-stream":mime));}
 static String mime(String url){String path=Playlist.httpUrl(url).encodedPath().toLowerCase(Locale.ROOT);if(path.endsWith(".mp3"))return "audio/mpeg";if(path.endsWith(".mp4")||path.endsWith(".m4v"))return "video/mp4";if(path.endsWith(".m4a"))return "audio/mp4";if(path.endsWith(".jpg")||path.endsWith(".jpeg"))return "image/jpeg";if(path.endsWith(".png"))return "image/png";return "application/octet-stream";}
 private DownloadPlanner(){}
}
